class_name HurtBox
extends Area2D

const DAMAGE_UNIT = 7.0

signal hurt(hurt_amount: int)

func _ready():
	var player = get_parent().get_node("player")

	connect("body_entered", func(body):
		if body.has_method("apply_damage"):
			body.apply_damage(DAMAGE_UNIT)
			hurt.emit(DAMAGE_UNIT)
			queue_free())

func apply_damage(v: int) -> void:
	emit_signal("hurt", v)

extends CharacterBody2D


var SPEED = 500.0 # px/s

@onready var sprite = $Sprite2D
@onready var animation_player = $AnimationPlayer
@onready var collision_shape_2d = $CollisionShape2D

func _physics_process(delta):
	if Input.is_action_pressed("ui_left"):
		move_and_slide(-SPEED * delta, Vector2.ZERO)
	elif Input.is_action_pressed("ui_right"):
		move_and_slide(SPEED * delta, Vector2.ZERO)

	if Input.is_action_just_pressed("ui_accept") and not is_on_floor():
		jump()

	collision_shape_2d.position.x += SPEED * delta

