class_name Coin extends Area2D

signal coin_collected(player: Player)

func _ready():
	$CollisionShape2D.set_deferred("monitoring_entered_area", true)


func _enter_tree():
	if not get_parent().is_in_group("player"):
		queue_free()
	else:
		connect("area_entered", func(area):
			if area.is_in_group("player"):
				emit_signal("coin_collected", get_parent())


